using Xunit;

public class U09_AlarmsTest
{
    [Fact]
    public void Controller_Reports_Proximal_Tube_Connected()
    {
        // Arrange
        var controller = new AlarmController();

        // Act
        var isConnected = controller.IsProximalTubeConnected();

        // Assert
        Assert.True(isConnected);
    }

    [Fact]
    public void GUI_Computes_Proximal_Tube_Disconnect_Alarm()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.ComputeProximalTubeDisconnectAlarm();

        // Assert
        Assert.True(gui.IsProximalTubeDisconnectAlarmActive());
    }

    [Fact]
    public void GUI_Detects_Obstruction()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        gui.DetectObstruction(100);

        // Assert
        Assert.True(gui.IsObstructionAlarmActive());
    }

    [Fact]
    public void GUI_Computes_Leakage()
    {
        // Arrange
        var gui = new AlarmGUI();

        // Act
        var leakage = gui.ComputeLeakage(100);

        // Assert
        Assert.Equal(0, leakage);
    }
}
